const items = $input.all();
const results = [];

for (const item of items) {
  const base64 = item.json.body?.resumeBase64 || item.json.resumeBase64;

  if (!base64) {
    throw new Error('No resumeBase64 field found in payload.');
  }

  const buffer = Buffer.from(base64, 'base64');
  const fileName = item.json.body?.resumeFilename || 'resume.pdf';

  const binaryData = await this.helpers.prepareBinaryData(
    buffer,
    fileName,
    'application/pdf'
  );

  results.push({
    json: item.json,
    binary: { data: binaryData }
  });
}

return results;

// Defensive JSON parsing: Gemini occasionally wraps output in markdown fences
// or adds stray text despite instructions. Strip and validate before responding.
const raw = $input.first().json.output ?? $input.first().json.text ?? '';

let cleaned = String(raw).trim();
cleaned = cleaned.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (err) {
  return [{
    json: {
      error: true,
      message: 'Model output was not valid JSON',
      rawOutput: cleaned
    }
  }];
}

if (!parsed.matchScore || typeof parsed.matchScore.percentage !== 'number') {
  return [{
    json: {
      error: true,
      message: 'JSON parsed but did not match expected schema',
      rawOutput: parsed
    }
  }];
}

// Clamp percentage defensively
parsed.matchScore.percentage = Math.max(0, Math.min(100, Math.round(parsed.matchScore.percentage)));

return [{ json: parsed }];
